DROP TABLE IF EXISTS `examenes_examenescargo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `examenes_examenescargo` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `fecha_creacion` datetime(6) NOT NULL,
  `cargo_id` int NOT NULL,
  `empresa_id` int NOT NULL,
  `examen_id` int NOT NULL,
  `tipo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'INGRESO',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_empresa_cargo_examen_tipo` (`empresa_id`,`cargo_id`,`examen_id`,`tipo`),
  KEY `examenes_examenescargo_cargo_id_a3bc8713_fk_cargo_idCargo` (`cargo_id`),
  KEY `fk_examenes_examenescargo_examen` (`examen_id`),
  KEY `idx_tipo` (`tipo`),
  KEY `idx_empresa_id` (`empresa_id`),
  CONSTRAINT `examenes_examenescargo_cargo_id_a3bc8713_fk_cargo_idCargo` FOREIGN KEY (`cargo_id`) REFERENCES `cargo` (`idCargo`),
  CONSTRAINT `examenes_examenescargo_empresa_id_bd5849c5_fk_epresa_Idempresa` FOREIGN KEY (`empresa_id`) REFERENCES `epresa` (`Idempresa`),
  CONSTRAINT `fk_examenes_examenescargo_examen` FOREIGN KEY (`examen_id`) REFERENCES `examenes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6435 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
