  CONSTRAINT `respuestas_colaboradores_ibfk_3` FOREIGN KEY (`idRespuesta`) REFERENCES `respuestas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56728 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
